#include <WiFi.h>

void setup() {
  Serial.begin(115200);
  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
}

void loop() {
  Serial.println("Scanning...");
  int found = WiFi.scanNetworks();
  Serial.print("Found ");
  Serial.print(found);
  Serial.println(" networks");
  for (int i = 0; i < found; i++) {
    Serial.print(WiFi.SSID(i));   // the network's name
    Serial.print("  ");
    Serial.print(WiFi.RSSI(i));   // its strength
    Serial.println(" dBm");
  }
  delay(5000);
}

