#include <WiFi.h>
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

Adafruit_SSD1306 display(128, 64, &Wire, -1);

// -90 dBm is very weak, -30 dBm is very strong: 0 to 4 bars.
int bars(int rssi) {
  if (rssi > -55) return 4;
  if (rssi > -67) return 3;
  if (rssi > -75) return 2;
  if (rssi > -85) return 1;
  return 0;
}

void setup() {
  Serial.begin(115200);
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  display.setTextColor(SSD1306_WHITE);
  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
}

void loop() {
  int found = WiFi.scanNetworks();
  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.print("WiFi radar: ");
  display.println(found);
  // Up to 6 networks, one per line: name, then bars.
  for (int i = 0; i < found && i < 6; i++) {
    int y = 12 + i * 9;
    display.setCursor(0, y);
    display.print(WiFi.SSID(i).substring(0, 14));
    for (int b = 0; b < bars(WiFi.RSSI(i)); b++) {
      display.fillRect(100 + b * 6, y + 6 - b * 2, 4, 2 + b * 2, SSD1306_WHITE);
    }
  }
  display.display();
  Serial.println("Scanned");
  delay(5000);
}
